const fs = require('fs');
const initSqlJs = require('sql.js');
initSqlJs().then(SQL => {
  const buf = fs.readFileSync('/workspace/world.db');
  const db = new SQL.Database(buf);
  const res = db.exec('SELECT name FROM sqlite_master WHERE type=\"table\"');
  console.log(JSON.stringify(res));
});
" 2>/dev/null

