NODE_PATH=$(npm root -g) node -e "
const db = require('better-sqlite3')('/workspace/world.db');
// Check products table schema
const schema = db.prepare(\"PRAGMA table_info('products')\").all();
console.log('Products schema:', JSON.stringify(schema, null, 2));
// Look for the product
const product = db.prepare(\"SELECT * FROM products WHERE product_id = 'PROD-2028EE'\").all();
console.log('Product:', JSON.stringify(product, null, 2));
"

